describe("ReviewSession docSwap (#115 rhythm edits)", () => {
  const CANONICAL = {
    projectId: "pj-test",
    revision: "rev-base",
    content: { parts: [] },
  };

  function engineDoc(): XmlScoreDocument {
    return new XmlScoreDocument({
      concertXml,
      hornXml,
      revisionId: "rev-base",
      issues: [],
      canonicalDocument: CANONICAL,
    });
  }

  it("undo/redo swap the document content back and forth", () => {
    const doc = engineDoc();
    const session = new ReviewSession(doc);
    const prev = doc.contentSnapshot!();
    const next = {
      concertXml: hornXml, // swap bodies so the change is observable
      hornXml: concertXml,
      revisionId: "rev-edited",
      canonicalDocument: { ...CANONICAL, revision: "rev-edited" },
    };
    doc.replaceContent!(next);
    expect(doc.revisionId).toBe("rev-edited");

    const edit = session.commitDocSwap(prev, next);
    expect(edit).not.toBeNull();
    expect(session.canUndo).toBe(true);

    session.undo();
    expect(doc.revisionId).toBe("rev-base");
    expect(doc.musicXml("concert")).toContain("<note");
    expect(doc.contentSnapshot!().concertXml).toBe(concertXml);
    expect(doc.canonicalDocument!()).toBe(CANONICAL);

    session.redo();
    expect(doc.revisionId).toBe("rev-edited");
    expect(doc.contentSnapshot!().concertXml).toBe(hornXml);
    expect((doc.canonicalDocument!() as { revision: string }).revision).toBe(
      "rev-edited",
    );
  });

  it("note edits and decisions survive a content swap (stable ids)", () => {
    const doc = engineDoc();
    const session = new ReviewSession(doc);
    session.editNote("sn-000012", { pitchDelta: 2 });
    const prev = doc.contentSnapshot!();
    const next = { ...prev, revisionId: "rev-edited" };
    doc.replaceContent!(next);
    session.commitDocSwap(prev, next);
    expect(session.noteEditOf("sn-000012").pitchDelta).toBe(2);
    session.undo();
    expect(doc.revisionId).toBe("rev-base");
    expect(session.noteEditOf("sn-000012").pitchDelta).toBe(2);
  });

  it("#225: a new revision drops stale issues; undo restores them", () => {
    const ISSUE = {
      id: "ri-000001",
      scoreRevision: "rev-base",
      canonicalNoteIds: ["sn-000012"],
      timeRange: { startSec: 0, endSec: 0.5 },
      reason: "low_model_confidence" as const,
      severity: "caution" as const,
      evidence: {},
      status: "open" as const,
    };
    const doc = new XmlScoreDocument({
      concertXml,
      hornXml,
      revisionId: "rev-base",
      issues: [ISSUE],
      canonicalDocument: CANONICAL,
    });
    doc.recordReviewDecision("ri-000001", "accepted");
    expect(doc.reviewIssues()[0].status).toBe("accepted");

    const prev = doc.contentSnapshot!();
    const next = { ...prev, revisionId: "rev-edited" };
    doc.replaceContent!(next);
    // The old revision's issue must not bleed onto the new revision.
    expect(doc.reviewIssues()).toHaveLength(0);

    // Undo swaps back to rev-base — its issue set and decision return.
    doc.replaceContent!(prev);
    expect(doc.reviewIssues()).toHaveLength(1);
    expect(doc.reviewIssues()[0].status).toBe("accepted");
  });

  it("returns null when the document cannot swap content", () => {
    // A minimal port without the optional #115 methods — e.g. a future
    // non-engine adapter. Rhythm edits stay honestly unavailable there.
    const bare: ScoreDocumentPort = {
      revisionId: "rev-bare",
      editVersion: 0,
      meta: {
        title: "",
        tempoBpm: null,
        meter: null,
        keyFifths: null,
        keyChanges: [],
        swingFeel: false,
        measureCount: 0,
        noteCount: 0,
      },
      musicXml: () => "",
      reviewIssues: () => [],
      recordReviewDecision: () => undefined,
      noteEdits: () => new Map(),
      setNoteEdit: () => undefined,
    };
    const session = new ReviewSession(bare);
    const snap = {
      concertXml: "",
      hornXml: "",
      revisionId: "rev-x",
      canonicalDocument: null,
    };
    expect(session.commitDocSwap(snap, snap)).toBeNull();
    expect(session.canUndo).toBe(false);
  });

  it("fixture documents have no canonical payload — rhythm edits gate out", () => {
    const doc = createFixtureScoreDocument();
    expect(doc.canonicalDocument?.() ?? null).toBeNull();
  });
});

// @vitest-environment jsdom
/**
 * Score note-edit transform tests (UI-050): semitone pitch shifts and
 * delete/restore applied to canonical `sn-*` notes in MusicXML.
 */
import { describe, expect, it } from "vitest";
import concertXml from "./fixtures/score_concert.musicxml?raw";
import {
  applyNoteEdits,
  enharmonicRespell,
  isEmptyNoteEdit,
  NO_NOTE_EDIT,
  shiftPitch,
  type ScoreNoteEdit,
} from "./scoreEdits";

const parse = (xml: string) =>
  new DOMParser().parseFromString(xml, "application/xml");

function noteXml(xml: string, hsId: string): Element | null {
  return parse(xml).querySelector(`note[id="${hsId}"]`);
}

describe("shiftPitch spelling", () => {
  it("ascending shifts respell with sharps", () => {
    expect(shiftPitch("C", 0, 4, 1)).toEqual({ step: "C", alter: 1, octave: 4 });
    expect(shiftPitch("F", 0, 4, 1)).toEqual({ step: "F", alter: 1, octave: 4 });
    expect(shiftPitch("B", 0, 4, 1)).toEqual({ step: "C", alter: 0, octave: 5 });
  });

  it("descending shifts respell with flats", () => {
    expect(shiftPitch("D", 0, 4, -1)).toEqual({ step: "D", alter: -1, octave: 4 });
    expect(shiftPitch("C", 0, 4, -1)).toEqual({ step: "B", alter: 0, octave: 3 });
    expect(shiftPitch("A", 0, 4, -2)).toEqual({ step: "G", alter: 0, octave: 4 });
  });

  it("natural neighbours never produce E#/Fb spellings", () => {
    expect(shiftPitch("E", 0, 4, 1)).toEqual({ step: "F", alter: 0, octave: 4 });
    expect(shiftPitch("F", 0, 4, -1)).toEqual({ step: "E", alter: 0, octave: 4 });
  });

  it("delta 0 is a no-op", () => {
    expect(shiftPitch("G", 0, 4, 0)).toBeNull();
    expect(isEmptyNoteEdit(NO_NOTE_EDIT)).toBe(true);
  });
});

describe("applyNoteEdits", () => {
  it("returns the original string when no edits apply", () => {
    expect(applyNoteEdits(concertXml, new Map())).toBe(concertXml);
    const foreign = new Map<string, ScoreNoteEdit>([
      ["sn-999999", { pitchDelta: 1, deleted: false }],
    ]);
    expect(applyNoteEdits(concertXml, foreign)).toBe(concertXml);
  });

  it("shifts a canonical note's pitch by semitones", () => {
    // Fixture sn-000012 is B♭3 (B, alter -1, octave 3) → +1 = B natural 3.
    const before = noteXml(concertXml, "hs-sn-000012")!;
    expect(before.querySelector("pitch step")!.textContent).toBe("B");
    expect(before.querySelector("pitch alter")!.textContent).toBe("-1");
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 1, deleted: false }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    expect(after).not.toBe(concertXml);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("pitch step")!.textContent).toBe("B");
    // alter 0 is omitted from MusicXML rather than written as "0".
    expect(note.querySelector("pitch alter")).toBeNull();
    expect(note.querySelector("pitch octave")!.textContent).toBe("3");
    // The accidental element mirrors the respelling (B♭ → B natural has
    // no accidental mark; Verovio re-derives courtesy accidentals).
    expect(note.querySelector("accidental")).toBeNull();
  });

  it("delete renders the note as a same-id rest (timing preserved)", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 0, deleted: true }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("rest")).not.toBeNull();
    expect(note.querySelector("pitch")).toBeNull();
    // Duration survives — the measure's beat math is untouched.
    expect(note.querySelector("duration")).not.toBeNull();
  });

  it("restore removes the edit so the original notation returns", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 0, deleted: true }],
    ]);
    const deleted = applyNoteEdits(concertXml, edits);
    edits.set("sn-000012", NO_NOTE_EDIT);
    // An identity edit maps back to the untouched document.
    expect(applyNoteEdits(concertXml, new Map())).toBe(concertXml);
    expect(deleted).not.toBe(concertXml);
  });

  it("enharmonic respells the same sounding pitch (#114)", () => {
    // sn-000012 is Bb3 -> respelled as A#3 (same MIDI 58).
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 0, deleted: false, enharmonic: true }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("pitch step")!.textContent).toBe("A");
    expect(note.querySelector("pitch alter")!.textContent).toBe("1");
    expect(note.querySelector("pitch octave")!.textContent).toBe("3");
    expect(note.querySelector("accidental")!.textContent).toBe("sharp");
  });

  it("enharmonic applies after a pitch shift", () => {
    // Bb3 +3 semitones = C#4 (shift respells sharp-side); respelled
    // -> Db4 (same MIDI 61).
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 3, deleted: false, enharmonic: true }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("pitch step")!.textContent).toBe("D");
    expect(note.querySelector("pitch alter")!.textContent).toBe("-1");
    expect(note.querySelector("pitch octave")!.textContent).toBe("4");
  });

  /* #246: deleting chord members must keep the <chord/> structure valid. */

  const chordXml = `<?xml version="1.0"?><score-partwise><part><measure number="1">
    <note id="hs-sn-000001"><pitch><step>C</step><octave>4</octave></pitch><duration>4</duration></note>
    <note id="hs-sn-000002"><chord/><pitch><step>E</step><octave>4</octave></pitch><duration>4</duration></note>
    <note id="hs-sn-000003"><chord/><pitch><step>G</step><octave>4</octave></pitch><duration>4</duration></note>
    <note id="hs-sn-000004"><pitch><step>D</step><octave>4</octave></pitch><duration>4</duration></note>
  </measure></part></score-partwise>`;

  const chordNotes = (xml: string) =>
    Array.from(parse(xml).querySelectorAll("measure > note"));

  it("deleting a non-root member drops it without a chord-rest", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000002", { pitchDelta: 0, deleted: true }],
    ]);
    const notes = chordNotes(applyNoteEdits(chordXml, edits));
    expect(notes).toHaveLength(3);
    expect(notes[0].querySelector("pitch step")!.textContent).toBe("C");
    expect(notes[0].querySelector("chord")).toBeNull();
    expect(notes[1].querySelector("chord")).not.toBeNull();
    expect(notes[1].querySelector("pitch step")!.textContent).toBe("G");
    // No chord-rest anywhere.
    expect(
      notes.some(
        (n) =>
          n.querySelector(":scope > chord") && n.querySelector(":scope > rest"),
      ),
    ).toBe(false);
  });

  it("deleting the root promotes the next pitched member", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000001", { pitchDelta: 0, deleted: true }],
    ]);
    const notes = chordNotes(applyNoteEdits(chordXml, edits));
    expect(notes).toHaveLength(3);
    // E4 is now the root: pitched, no <chord/> tag.
    expect(notes[0].querySelector("pitch step")!.textContent).toBe("E");
    expect(notes[0].querySelector("chord")).toBeNull();
    expect(notes[1].querySelector("chord")).not.toBeNull();
    expect(notes[1].querySelector("pitch step")!.textContent).toBe("G");
  });

  it("deleting every member collapses to a single rest", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000001", { pitchDelta: 0, deleted: true }],
      ["sn-000002", { pitchDelta: 0, deleted: true }],
      ["sn-000003", { pitchDelta: 0, deleted: true }],
    ]);
    const notes = chordNotes(applyNoteEdits(chordXml, edits));
    expect(notes).toHaveLength(2);
    expect(notes[0].querySelector("rest")).not.toBeNull();
    expect(notes[0].querySelector("chord")).toBeNull();
    expect(notes[1].querySelector("pitch step")!.textContent).toBe("D");
  });
});

describe("enharmonicRespell", () => {
  it("flips sharp/flat families keeping the same pitch class", () => {
    expect(enharmonicRespell("C", 1, 4)).toEqual({
      step: "D",
      alter: -1,
      octave: 4,
    });
    expect(enharmonicRespell("B", -1, 3)).toEqual({
      step: "A",
      alter: 1,
      octave: 3,
    });
  });

  it("keeps the sounding octave across boundary spellings", () => {
    // B#3 (MIDI 60) -> C4; Cb4 (MIDI 59) -> B3.
    expect(enharmonicRespell("B", 1, 3)).toEqual({
      step: "C",
      alter: 0,
      octave: 4,
    });
    expect(enharmonicRespell("C", -1, 4)).toEqual({
      step: "B",
      alter: 0,
      octave: 3,
    });
  });

  it("returns null when the other family is the same spelling", () => {
    // Naturals have no single-accidental partner (E#/Cb spellings are
    // deliberately not produced), so respell is a no-op there.
    expect(enharmonicRespell("F", 0, 4)).toBeNull();
    expect(enharmonicRespell("C", 0, 4)).toBeNull();
  });
});

/**
 * Score note edits (UI-050, GUI_UX_SPEC §13 簡易音符修正).
 *
 * The review workspace's correction set is deliberately narrow: semitone
 * pitch shift and delete/restore. Edits are expressed against canonical
 * `sn-*` note ids and applied to the document's MusicXML by
 * `applyNoteEdits` — the same transform runs on the concert and F管
 * presentations (identical `hs-sn-*` ids), so both views stay consistent
 * and any consumer of `musicXml()` sees the corrected document.
 *
 * Spelling policy: ascending shifts respell with sharps, descending with
 * flats — deterministic and direction-aware, matching the P4 prototype's
 * convention. Enharmonic re-spelling that keeps pitch is a separate spec
 * item and not part of this transform.
 */
import { canonicalNoteIdFromMusicxml } from "./ids";

/** One canonical note's user edit - cumulative, never incremental state. */
export interface ScoreNoteEdit {
  /** Semitone offset vs. the document's emitted pitch (0 = unchanged). */
  readonly pitchDelta: number;
  /** User deleted this note - rendered as a rest so measure timing stays
   *  intact (a removal would shift every later onset). */
  readonly deleted: boolean;
  /** #114 (spec 13): enharmonic respell toggle - the sounding pitch is
   *  unchanged; the written spelling flips to the other accidental
   *  family (sharp <-> flat). Applied after pitchDelta. */
  readonly enharmonic?: boolean;
}

/** The identity edit - absence of a map entry means the same thing. */
export const NO_NOTE_EDIT: ScoreNoteEdit = {
  pitchDelta: 0,
  deleted: false,
  enharmonic: false,
};

export function isEmptyNoteEdit(edit: ScoreNoteEdit): boolean {
  return (
    edit.pitchDelta === 0 && !edit.deleted && !(edit.enharmonic ?? false)
  );
}

const STEP_PC: Record<string, number> = {
  C: 0,
  D: 2,
  E: 4,
  F: 5,
  G: 7,
  A: 9,
  B: 11,
};

/** pitch class → [step, alter] spellings. Ascending shifts use sharps,
 *  descending use flats (so E+1 = F, D-1 = D♭ — never E♯/F♭ here). */
const SPELL_SHARP: ReadonlyArray<readonly [string, number]> = [
  ["C", 0],
  ["C", 1],
  ["D", 0],
  ["D", 1],
  ["E", 0],
  ["F", 0],
  ["F", 1],
  ["G", 0],
  ["G", 1],
  ["A", 0],
  ["A", 1],
  ["B", 0],
];
const SPELL_FLAT: ReadonlyArray<readonly [string, number]> = [
  ["C", 0],
  ["D", -1],
  ["D", 0],
  ["E", -1],
  ["E", 0],
  ["F", 0],
  ["G", -1],
  ["G", 0],
  ["A", -1],
  ["A", 0],
  ["B", -1],
  ["B", 0],
];

const ACCIDENTAL_NAME: Record<number, string> = {
  "-2": "flat-flat",
  "-1": "flat",
  "1": "sharp",
  "2": "double-sharp",
};

/**
 * Shift a spelled pitch by `delta` semitones and return the new
 * (step, alter, octave) spelling. Returns null for unspellable input.
 */
export function shiftPitch(
  step: string,
  alter: number,
  octave: number,
  delta: number,
): { step: string; alter: number; octave: number } | null {
  const pc0 = STEP_PC[step];
  if (pc0 === undefined || delta === 0) return null;
  const midi = (octave + 1) * 12 + pc0 + alter + delta;
  const pc = ((midi % 12) + 12) % 12;
  const [s, a] = (delta > 0 ? SPELL_SHARP : SPELL_FLAT)[pc];
  return { step: s, alter: a, octave: Math.floor(midi / 12) - 1 };
}

/** #114 (spec 13 異名同音): respell the SAME sounding pitch in the other
 *  accidental family (sharp <-> flat). Prefers a single accidental; when
 *  both candidates need a double accidental the flat family wins (B# ->
 *  C keeps naturals stable). Returns null for unspellable input. */
export function enharmonicRespell(
  step: string,
  alter: number,
  octave: number,
): { step: string; alter: number; octave: number } | null {
  const pc0 = STEP_PC[step];
  if (pc0 === undefined) return null;
  const midi = (octave + 1) * 12 + pc0 + alter;
  const pc = ((midi % 12) + 12) % 12;
  const sharp = SPELL_SHARP[pc];
  const flat = SPELL_FLAT[pc];
  const currentIsFlat = alter < 0;
  const [first, second] = currentIsFlat ? [sharp, flat] : [flat, sharp];
  const pick = Math.abs(first[1]) <= 1 ? first : second;
  // No-op guard: the other family is the same spelling (naturals).
  if (pick[0] === step && pick[1] === alter) return null;
  // STEP_PC+alter can leave [0,11] (B#=12, Cb=-1), so solve the octave
  // from midi - (step+alter) instead of midi/12.
  return {
    step: pick[0],
    alter: pick[1],
    octave: Math.floor((midi - (STEP_PC[pick[0]] + pick[1])) / 12) - 1,
  };
}

function setChildText(
  parent: Element,
  doc: XMLDocument,
  tag: string,
  text: string | null,
  before?: Element | null,
): void {
  const existing = parent.querySelector(`:scope > ${tag}`);
  if (text === null) {
    existing?.remove();
    return;
  }
  if (existing) {
    existing.textContent = text;
    return;
  }
  const el = doc.createElement(tag);
  el.textContent = text;
  parent.insertBefore(el, before ?? null);
}

/** Write a (step, alter, octave) spelling back into <pitch> and sync the
 *  <accidental> element so the rendered glyph matches. */
function writeSpelling(
  noteEl: Element,
  pitch: Element,
  doc: XMLDocument,
  next: { step: string; alter: number; octave: number },
): void {
  const octaveEl = pitch.querySelector("octave");
  setChildText(pitch, doc, "step", next.step, pitch.querySelector("alter") ?? octaveEl);
  setChildText(
    pitch,
    doc,
    "alter",
    next.alter === 0 ? null : String(next.alter),
    octaveEl,
  );
  setChildText(pitch, doc, "octave", String(next.octave));
  const acc = noteEl.querySelector(":scope > accidental");
  const accName = ACCIDENTAL_NAME[next.alter];
  if (accName === undefined) acc?.remove();
  else if (acc) acc.textContent = accName;
  else {
    const el = doc.createElement("accidental");
    el.textContent = accName;
    noteEl.appendChild(el);
  }
}

/** Read the note's current (step, alter, octave), or null for rests /
 *  unspellable pitches. */
function readSpelling(
  noteEl: Element,
): { step: string; alter: number; octave: number } | null {
  const pitch = noteEl.querySelector(":scope > pitch");
  if (!pitch) return null; // already a rest - nothing to transpose
  const step = pitch.querySelector("step")?.textContent ?? "";
  const alterText = pitch.querySelector("alter")?.textContent;
  const octaveText = pitch.querySelector("octave")?.textContent;
  const octave = octaveText != null ? Number(octaveText) : NaN;
  if (!Number.isFinite(octave) || !(step in STEP_PC)) return null;
  return { step, alter: alterText != null ? Number(alterText) : 0, octave };
}

/** Rewrite a <note>'s <pitch>/<alter>/<octave> and its <accidental> text
 *  so the rendered glyph matches the shifted sounding pitch. */
function shiftNotePitch(noteEl: Element, doc: XMLDocument, delta: number): void {
  const cur = readSpelling(noteEl);
  if (!cur) return;
  const next = shiftPitch(cur.step, cur.alter, cur.octave, delta);
  if (!next) return;
  writeSpelling(noteEl, noteEl.querySelector(":scope > pitch")!, doc, next);
}

/** #114: enharmonic respell - same sounding pitch, other accidental
 *  family (spec 13). */
function respellNotePitch(noteEl: Element, doc: XMLDocument): void {
  const cur = readSpelling(noteEl);
  if (!cur) return;
  const next = enharmonicRespell(cur.step, cur.alter, cur.octave);
  if (!next) return;
  writeSpelling(noteEl, noteEl.querySelector(":scope > pitch")!, doc, next);
}

/** Convert a pitched <note> into a same-duration rest, keeping the
 *  `hs-sn-*` id so canonical identity (selection, issue links) survives.
 *  Ties/notations/beams that only make sense for a pitch are dropped. */
function noteToRest(noteEl: Element, doc: XMLDocument): void {
  const pitch = noteEl.querySelector(":scope > pitch");
  if (!pitch) return; // already a rest
  const rest = doc.createElement("rest");
  noteEl.replaceChild(rest, pitch);
  for (const tag of ["accidental", "tie", "notations", "stem", "beam"] as const) {
    for (const el of Array.from(noteEl.querySelectorAll(`:scope > ${tag}`))) {
      el.remove();
    }
  }
}

/** #246: after deletions, rebuild each <chord/> group so the MusicXML
 *  stays structurally valid. A chord group is a pitched root <note>
 *  followed by <note> elements carrying <chord/>; deletions can leave
 *  a chord-rest (<chord/><rest/>), a rest-root with pitched members
 *  dangling off it, or several same-position rests where one member
 *  survived. Walk each measure's direct children (voices are separated
 *  by <backup>/<forward>, which also break a group) and normalize:
 *  - first surviving pitched member becomes the root (its <chord/> is
 *    removed);
 *  - rest members inside a group are dropped (a chord rest is
 *    meaningless — the surviving members already occupy the slot);
 *  - a group with no pitched member collapses to a single rest. */
function normalizeChords(doc: XMLDocument): void {
  const isPitched = (el: Element): boolean =>
    el.querySelector(":scope > pitch") !== null;
  const isChordMember = (el: Element): boolean =>
    el.querySelector(":scope > chord") !== null;
  const dropChordTag = (el: Element): void => {
    for (const c of Array.from(el.querySelectorAll(":scope > chord"))) {
      c.remove();
    }
  };

  const flush = (group: Element[]): void => {
    if (group.length === 0) return;
    const pitched = group.filter(isPitched);
    if (pitched.length === 0) {
      // All members deleted: keep ONE rest for the slot, drop the rest.
      const [keep, ...extra] = group;
      dropChordTag(keep);
      for (const el of extra) el.remove();
      return;
    }
    // Promote the first pitched member to root, then drop rest members
    // (their duration is already covered by the surviving chord).
    dropChordTag(pitched[0]);
    for (const el of group) {
      if (!isPitched(el)) el.remove();
    }
  };

  for (const measure of Array.from(doc.querySelectorAll("measure"))) {
    let group: Element[] = [];
    for (const child of Array.from(measure.children)) {
      if (child.tagName === "note") {
        if (isChordMember(child)) {
          group.push(child);
        } else {
          flush(group);
          group = [child];
        }
      } else if (child.tagName === "backup" || child.tagName === "forward") {
        flush(group);
        group = [];
      }
    }
    flush(group);
  }
}

/**
 * Apply canonical-note edits to a MusicXML document and return the new
 * XML string. Unedited input short-circuits to the original string so the
 * render path can tell "no change" apart cheaply.
 */
export function applyNoteEdits(
  xml: string,
  edits: ReadonlyMap<string, ScoreNoteEdit>,
): string {
  if (edits.size === 0) return xml;
  const doc = new DOMParser().parseFromString(xml, "application/xml");
  if (doc.querySelector("parsererror")) {
    throw new Error("MusicXML parse failed");
  }
  let changed = false;
  for (const noteEl of Array.from(doc.querySelectorAll("note[id]"))) {
    const canonical = canonicalNoteIdFromMusicxml(noteEl.getAttribute("id") ?? "");
    if (!canonical) continue;
    const edit = edits.get(canonical);
    if (!edit) continue;
    if (edit.deleted) {
      noteToRest(noteEl, doc);
      changed = true;
    } else {
      // pitchDelta first, then the enharmonic respell of the shifted
      // pitch (edit semantics: respell applies to the edited spelling).
      if (edit.pitchDelta !== 0) {
        shiftNotePitch(noteEl, doc, edit.pitchDelta);
        changed = true;
      }
      if (edit.enharmonic) {
        respellNotePitch(noteEl, doc);
        changed = true;
      }
    }
  }
  if (!changed) return xml;
  normalizeChords(doc);
  return new XMLSerializer().serializeToString(doc);
}

/**
 * XmlScoreDocument — `ScoreDocumentPort` over arbitrary MusicXML bodies
 * (ENG-002).
 *
 * The fixture adapter proved the contract; this is the general form the
 * real engine result slots into: the transcription job returns
 * `musicXmlConcert` + `musicXmlHornF` (same canonical `hs-sn-*` ids in
 * both — the export layer's contract), the `sr-*` revision id, and the
 * typed review issues. Review decisions and note edits live here, keyed
 * to `revisionId` — a new score revision constructs a fresh document,
 * so stale decisions are never carried across (domain/review.py rule).
 */
import type { PitchViewSetting } from "../commands/types";
import type { ScoreDocumentMeta, ScoreDocumentPort } from "./document";
import { parseScoreDoc } from "./scoreDoc";
import type { ReviewIssueStatus, ScoreReviewIssue } from "./review";
import {
  applyNoteEdits,
  isEmptyNoteEdit,
  type ScoreNoteEdit,
} from "./scoreEdits";

export interface XmlScoreDocumentSources {
  /** Canonical sounding-pitch MusicXML (`<sound tempo>` etc. drive meta). */
  readonly concertXml: string;
  /** Written-pitch F管 presentation of the SAME canonical notes. */
  readonly hornXml: string;
  /** `sr-*`/`rev-*` revision id the decisions/edits bind to. */
  readonly revisionId: string;
  /** Engine review issues for this revision (`[]` = honestly clean). */
  readonly issues: readonly ScoreReviewIssue[];
  /** #115: canonical scoreDocument dict — the base the engine's
   *  `score.edit` re-realizes from (undefined for fixture/dev). */
  readonly canonicalDocument?: unknown;
}

export class XmlScoreDocument implements ScoreDocumentPort {
  private _revisionId: string;
  private _meta: ScoreDocumentMeta;
  private concertXml: string;
  private hornXml: string;
  private canonicalDoc: unknown | null;
  private issues: readonly ScoreReviewIssue[];
  private decisions = new Map<string, ReviewIssueStatus>();
  /** #225: decisions/issues are revision-bound — a score.edit swap
   *  mints a new revision, so the old revision's set is stashed here
   *  and a swap back (undo) restores exactly that revision's state. */
  private readonly issuesByRevision = new Map<
    string,
    readonly ScoreReviewIssue[]
  >();
  private readonly decisionsByRevision = new Map<
    string,
    Map<string, ReviewIssueStatus>
  >();
  private readonly edits = new Map<string, ScoreNoteEdit>();
  private editCounter = 0;

  constructor(src: XmlScoreDocumentSources) {
    this._revisionId = src.revisionId;
    this.issues = src.issues;
    this.concertXml = src.concertXml;
    this.hornXml = src.hornXml;
    this.canonicalDoc = src.canonicalDocument ?? null;
    this._meta = XmlScoreDocument.computeMeta(src.concertXml);
  }

  private static computeMeta(xml: string): ScoreDocumentMeta {
    const doc = parseScoreDoc(xml);
    const canonical = new Set(
      doc.notes.map((n) => n.canonicalId).filter(Boolean),
    );
    return {
      title: doc.title,
      tempoBpm: doc.tempoBpm,
      meter: doc.meter,
      keyFifths: doc.keyFifths,
      keyChanges: doc.keyChanges,
      swingFeel: doc.swingFeel,
      measureCount: doc.measureCount,
      noteCount: canonical.size,
    };
  }

  get revisionId(): string {
    return this._revisionId;
  }

  get meta(): ScoreDocumentMeta {
    return this._meta;
  }

  get editVersion(): number {
    return this.editCounter;
  }

  musicXml(view: PitchViewSetting): string {
    const base = view === "hornF" ? this.hornXml : this.concertXml;
    return applyNoteEdits(base, this.edits);
  }

  reviewIssues(): readonly ScoreReviewIssue[] {
    return this.issues.map((issue) => {
      const decided = this.decisions.get(issue.id);
      return decided !== undefined ? { ...issue, status: decided } : issue;
    });
  }

  recordReviewDecision(issueId: string, status: ReviewIssueStatus): void {
    this.decisions.set(issueId, status);
    this.editCounter += 1;
  }

  noteEdits(): ReadonlyMap<string, ScoreNoteEdit> {
    return this.edits;
  }

  setNoteEdit(canonicalId: string, edit: ScoreNoteEdit | null): void {
    if (edit == null || isEmptyNoteEdit(edit)) this.edits.delete(canonicalId);
    else this.edits.set(canonicalId, edit);
    this.editCounter += 1;
  }

  /* ---- #115: engine rhythm edits swap content in place ---- */

  canonicalDocument(): unknown | null {
    return this.canonicalDoc;
  }

  contentSnapshot() {
    return {
      concertXml: this.concertXml,
      hornXml: this.hornXml,
      revisionId: this._revisionId,
      canonicalDocument: this.canonicalDoc,
    };
  }

  /** Swap XML bodies + revision + canonical payload in place. Meta is
   *  recomputed from the new concert XML (measure/note counts can move).
   *  Note edits and review decisions survive — canonical ids are stable,
   *  and the session's undo stack keeps working across the swap. */
  replaceContent(next: {
    concertXml: string;
    hornXml: string;
    revisionId: string;
    canonicalDocument: unknown;
  }): void {
    if (next.revisionId !== this._revisionId) {
      // #225: stash the outgoing revision's issue set + decisions, then
      // restore the incoming revision's own set (empty for a revision
      // never seen — a score.edit result carries no issue list).
      this.issuesByRevision.set(this._revisionId, this.issues);
      this.decisionsByRevision.set(this._revisionId, this.decisions);
      this.issues = this.issuesByRevision.get(next.revisionId) ?? [];
      this.decisions =
        this.decisionsByRevision.get(next.revisionId) ?? new Map();
    }
    this.concertXml = next.concertXml;
    this.hornXml = next.hornXml;
    this._revisionId = next.revisionId;
    this.canonicalDoc = next.canonicalDocument;
    this._meta = XmlScoreDocument.computeMeta(next.concertXml);
    this.editCounter += 1;
  }
}

/** Fields extracted from a completed transcription job's `result`. */
export interface EngineScoreDocumentInput {
  readonly concertXml: string;
  readonly hornXml: string;
  readonly revisionId: string;
  readonly issues: readonly ScoreReviewIssue[];
  /** #115: canonical scoreDocument dict from the job result. */
  readonly canonicalDocument?: unknown;
}

/**
 * Build the score document for a real transcription result. Returns
 * `null` when the payload is not usable (missing/invalid MusicXML) so
 * the caller can fall back honestly instead of mounting a broken score.
 */
export function createEngineScoreDocument(
  input: EngineScoreDocumentInput,
): ScoreDocumentPort | null {
  if (!input.concertXml || !input.hornXml) return null;
  try {
    return new XmlScoreDocument({
      concertXml: input.concertXml,
      hornXml: input.hornXml,
      revisionId: input.revisionId,
      issues: input.issues,
      canonicalDocument: input.canonicalDocument,
    });
  } catch {
    // parseScoreDoc throws on malformed MusicXML — a corrupt engine
    // payload must not take down the workspace.
    return null;
  }
}

/**
 * Extract the document input from `session.lastResult` (the completed
 * job's `result` payload). Returns `null` when the result carries no
 * MusicXML — e.g. the mock port's stand-in result — so callers fall
 * back to the fixture document in dev sessions.
 */
export function engineDocumentFromResult(
  result: unknown,
): EngineScoreDocumentInput | null {
  if (typeof result !== "object" || result === null) return null;
  const r = result as Record<string, unknown>;
  const concert = r.musicXmlConcert;
  const horn = r.musicXmlHornF;
  if (typeof concert !== "string" || typeof horn !== "string") return null;
  return {
    concertXml: concert,
    hornXml: horn,
    revisionId:
      typeof r.scoreRevision === "string" ? r.scoreRevision : "rev-engine",
    issues: [],
    canonicalDocument:
      typeof r.scoreDocument === "object" && r.scoreDocument !== null
        ? r.scoreDocument
        : undefined,
  };
}
